#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    vector<long long> small, large;

    for (long long i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            small.push_back(i);
            if (i != n / i)
                large.push_back(n / i);
        }
    }

    long long count = small.size() + large.size();
    if (k < 1 || k > count) {
        cout << -1;
    } else if (k <= static_cast<long long>(small.size())) {
        cout << small[k - 1];
    } else {
        cout << large[count - k];
    }

    return 0;
}

