#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, k;
    cin >> n >> k;

    vector<long long> divisors;
    for (long long i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i != n / i)
                divisors.push_back(n / i);
        }
    }

    sort(divisors.begin(), divisors.end());

    if (k < 1 || k > static_cast<long long>(divisors.size()))
        cout << -1;
    else
        cout << divisors[k - 1];

    return 0;
}

